{
  "identity": {
    "name": "North Star Kitchen and Bath Remodels",
    "location": "999 W Main St Suite 100, Boise, ID 83702",
    "claims": [
      {
        "statement": "The business operates under the name North Star Kitchen and Bath Remodels.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "North Star Kitchen and Bath Remodels"
      },
      {
        "statement": "The company lists its physical address in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "999 W Main St Suite 100, Boise, ID 83702"
      },
      {
        "statement": "The company states that it is a family-owned business serving Boise and the Treasure Valley area.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "As a family-owned business, we treat clients like family, providing personalized renovations that cater to every budget and always exceed expectations."
      }
    ]
  },
  "industry": {
    "industry": "Residential Remodeling (Kitchen and Bathroom Renovation)",
    "activities": [
      "Full-scale kitchen remodeling and design",
      "Full-scale bathroom renovation and shower remodeling",
      "Kitchen and bathroom cabinetry installation",
      "Countertop installation (granite, marble, quartz, wood, solid stone)",
      "Flooring installation (hardwood, ceramic tile, linoleum, vinyl plank)",
      "Bathtub refinishing"
    ],
    "claims": [
      {
        "statement": "The company provides kitchen and bath remodeling services in the Treasure Valley area.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "North Star Kitchen and Bath Remodels proudly brings over a decade of experience in the kitchen and bath remodeling industry to the Treasure Valley area."
      },
      {
        "statement": "The company installs kitchen cabinets, countertops, and flooring as part of its remodeling projects.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "North Star Kitchen and Bath Remodels offers a full line of beautiful kitchen cabinets in a wide range of materials and styles"
      },
      {
        "statement": "The company performs structural and electrical modifications only as part of full-scale kitchen or bathroom renovations rather than operating as a standalone HVAC, plumbing, or electrical service contractor.",
        "label": "inference",
        "sourceUrl": "https://northstarkitchenandbath.com/our-team-remodeling-contractors-boise/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://northstarkitchenandbath.com/",
    "claims": [
      {
        "statement": "The company's stated operating hours are Monday through Friday from 7 AM to 6 PM.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "Monday - Friday 7AM - 6PM"
      },
      {
        "statement": "The company serves Boise as well as surrounding communities including Caldwell, Star, and Nampa.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "We have created stunning kitchens and bathrooms for homes in Caldwell, Star, Nampa, and all cities in between"
      },
      {
        "statement": "The website sitemap lists a page for bathroom and kitchen remodel financing.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/sitemap/",
        "quote": "The Bathroom and Kitchen Remodel Financing Boise Customers Are Taking Advantage Of!"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company states its construction team and interior designers are qualified to manage complete tear-outs, load-bearing wall relocation, and electrical wiring.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/our-team-remodeling-contractors-boise/",
        "quote": "Our construction team and experienced interior designers are fully qualified to manage a complete tear-out and renovation of your space"
      }
    ],
    "limitations": "No state contractor license numbers, Idaho contractor registration numbers, or legal entity registration identifiers are displayed on the public website pages read."
  },
  "existingSoftware": [
    {
      "product": "WordPress content management system and plugins (Oxygen, WP Rocket, WP Review Slider Pro)",
      "purpose": "Website content management, page building, caching, and review display",
      "evidence": {
        "statement": "The homepage loads scripts from wp-content and wp-includes directories, including wp-review-slider-pro, oxygen, and wp-rocket plugins.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "https://northstarkitchenandbath.com/wp-content/plugins/wp-review-slider-pro/public/js/wprev-public.min.js?ver=10.2.9"
      }
    },
    {
      "product": "msgsndr.com embedded survey widget",
      "purpose": "Online lead capture and quote request survey form",
      "evidence": {
        "statement": "The website embeds an iframe widget from msgsndr.com alongside a form_embed.js script.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "https://msgsndr.com/widget/survey/cfRo4qkrDJntOyswr2xd"
      }
    },
    {
      "product": "CRM and marketing automation platform associated with msgsndr.com (commonly HighLevel / GoHighLevel)",
      "purpose": "Lead capture, CRM, and automated lead follow-up",
      "evidence": {
        "statement": "The msgsndr.com domain is typically used by the HighLevel marketing and CRM automation platform to host lead capture surveys and trigger automated workflows.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager and Google Analytics (gtag.js)",
      "purpose": "Website analytics and tag management",
      "evidence": {
        "statement": "The homepage loads Google Tag Manager and Google Analytics scripts.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=UA-138039080-1"
      }
    },
    {
      "product": "Cloudflare",
      "purpose": "Email address obfuscation and web performance/analytics beacon",
      "evidence": {
        "statement": "The homepage loads Cloudflare email decoding and Cloudflare Insights beacon scripts.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "https://northstarkitchenandbath.com/cdn-cgi/scripts/5c5dd728/cloudflare-static/email-decode.min.js"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The website prompts visitors to request free quotes and estimates via phone or embedded survey forms.",
      "label": "fact",
      "sourceUrl": "https://northstarkitchenandbath.com/kitchen-and-bath-remodel-boise/",
      "quote": "Get A Free Instant Quote"
    },
    {
      "statement": "The contact page meta description contains leftover template text referencing a 'Soft Wash' exterior cleaning system unrelated to kitchen and bath remodeling.",
      "label": "fact",
      "sourceUrl": "https://northstarkitchenandbath.com/contact/",
      "quote": "Keep in Touch and Experience our cutting-edge and highly effective “Soft Wash” system without damaging surfaces on your home or landscape."
    }
  ],
  "problems": [
    {
      "problem": "Potential delays in triaging or responding to web survey inquiries and quote requests outside of business hours.",
      "label": "hypothesis",
      "basis": "While the site embeds a msgsndr.com survey widget to capture quote requests, public pages do not confirm whether automated instant replies or staff notifications are actively configured."
    },
    {
      "problem": "Manual effort in tracking multi-week remodeling project estimates, supplier invoices (cabinets, countertops, flooring), and job costing.",
      "label": "hypothesis",
      "basis": "Full-scale kitchen and bath renovations involve multiple material suppliers (such as Dura Supreme, US Cabinet Depot, and Cosentino), which can require manual invoice and document coordination if not integrated into construction management software."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Embedded survey and CRM automation via msgsndr.com",
      "addresses": "Web lead capture and automated initial lead follow-up",
      "alreadyOwned": true
    },
    {
      "solution": "Construction and remodeling project management platforms (e.g., Buildertrend, CoConstruct, JobTread, or Houzz Pro)",
      "addresses": "Design-build estimating, client selections, project scheduling, and vendor invoice management",
      "alreadyOwned": false
    }
  ],
